def solve(g):
    H,W = len(g), len(g[0])
    sep = next(r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=0)
    sc = g[sep][0]
    seen=[[False]*W for _ in range(H)]; objs=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and g[r][c]!=sc and not seen[r][c]:
                col=g[r][c]; cells=[(r,c)]; seen[r][c]=True
                for dr,dc in ((0,1),(1,0)):
                    rr,cc=r+dr,c+dc
                    if rr<H and cc<W and g[rr][cc]==col and not seen[rr][cc]:
                        cells.append((rr,cc)); seen[rr][cc]=True
                objs.append(cells)
    sep_bottom = sep==H-1
    objs.sort(key=(lambda o: -max(r for r,c in o)) if sep_bottom else (lambda o: min(r for r,c in o)))
    out=[[0]*W for _ in range(H)]
    out[sep]=[sc]*W
    lo, hi = (0, sep-1) if sep_bottom else (sep+1, H-1)
    def free(cells): return all(lo<=a<=hi and out[a][b]==0 for a,b in cells)
    for o in objs:
        colv = g[o[0][0]][o[0][1]]
        vertical = o[0][1]==o[1][1]
        if sep_bottom:
            b = max(rr for rr,_ in o)   # bottom row
            while True:
                nb = b+1
                cand=[(b,o[0][1]),(nb,o[0][1])] if vertical else [(nb,c) for _,c in o]
                if not free(cand): break
                b = nb
            cells=[(b,o[0][1]),(b-1,o[0][1])] if vertical else [(b,c) for _,c in o]
        else:
            t = min(rr for rr,_ in o)   # top row
            while True:
                nt = t-1
                cand=[(nt,o[0][1]),(nt+1,o[0][1])] if vertical else [(nt,c) for _,c in o]
                if not free(cand): break
                t = nt
            cells=[(t,o[0][1]),(t+1,o[0][1])] if vertical else [(t,c) for _,c in o]
        for rr,cc in cells: out[rr][cc]=colv
    return out

